public static void main(String[] args) throws Exception {
    AReader input = new AReader();
    PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
    String string = input.next();
    HashMap<String, Integer> hs = new HashMap<String, Integer>();
    int inf = Integer.MAX_VALUE;
    for (int i = 0; i < string.length(); ++i) {
        String now = string.substring(0, i + 1);
        hs.put(now, inf);
    }
    hs.put("", 0);
    int n = input.nextInt();
    for (int i = 1; i <= n; ++i) {
        int x = input.nextInt();
        HashMap<String, Integer> may = new HashMap<String, Integer>();
        for (int j = 1; j <= x; ++j) {
            String string2 = input.next();
            for (String y : hs.keySet()) {
                String now = y + string2;
                if (now.length() > string.length() || !string.startsWith(now)) continue;
                int z = hs.get(y);
                if (may.get(now) == null) {
                    may.put(now, z + 1);
                } else {
                    int t = may.get(now);
                    if (t > z + 1)
                        may.put(now, z + 1);
                }
            }
        }
        for (String now : may.keySet()) {
            int y = may.get(now);
            int z = hs.get(now);
            if (y < z) hs.put(now, y);
        }
    }
    if (hs.get(string) == null || hs.get(string) == inf) {
        out.print("-1");
    } else {
        out.print(hs.get(string));
    }
    out.flush();
    out.close();
}
